def reconcile_order_quantities(requested,filled,canceled,open_quantity):
    values = (requested,filled,canceled,open_quantity)
    if any(type(v) is not int or not 0<=v<=1000000 for v in values):
        raise ValueError("expected bounded nonnegative integer shares, excluding bool")
    if requested==0 or requested!=filled+canceled+open_quantity:
        raise ValueError("order quantities do not reconcile")
    return {"filled":filled,"canceled":canceled,"open":open_quantity}

# This fixture assumes an acknowledged order for100shares and confirmed events.
print(reconcile_order_quantities(100,0,0,100))
print(reconcile_order_quantities(100,30,0,70))
# A cancel REQUEST alone does not move the remaining70into canceled.
print(reconcile_order_quantities(100,50,50,0))
try:
    reconcile_order_quantities(100,50,70,0)
except ValueError:
    print("inconsistent state rejected")

from fractions import Fraction

def quoted_buy_cost(price_cents,shares,fee_cents,available):
    if any(type(v) is not int or not 0<=v<=1000000
           for v in (price_cents,shares,fee_cents,available)):
        raise ValueError("expected bounded integer cents/shares, excluding bool")
    if price_cents==0 or shares==0:
        raise ValueError("price and requested shares must be positive")
    if available<shares:
        return None
    total = price_cents*shares+fee_cents
    return total,Fraction(total,shares)

# Synthetic same-instrument, same-currency snapshots, NOT available venues.
for name,price,fee,size in [("A",1000,50,100),("B",1001,0,100),("C",999,0,5)]:
    print(name,quoted_buy_cost(price,10,fee,size))
